def estimate_kolmogorov_via_compression(s, method='zlib'):
    if isinstance(s, str):
        s = s.encode('utf-8')
    if method == 'zlib':
        compressed = zlib.compress(s, level=9)
    elif method == 'gzip':
        buf = io.BytesIO()
        with gzip.GzipFile(fileobj=buf, mode='wb', compresslevel=9) as f:
            f.write(s)
        compressed = buf.getvalue()
    return len(compressed)
